302	     * or {@code "UNKNOWN"} when neither yields a region. Before the customer code is assigned the
303	     * region is resolved directly from the postcode and city.
304	     */
305	    @Transient
306	    public String getLocality() {
307	        if (this.customerCode == null) {
308	            return LocalityResolver.regionFor(this.postcode, this.city);
309	        }
310	        int separator = this.customerCode.indexOf('-');
