323	    /**
324	     * Return this owner's identity key, the single derived value all duplicate detection is based
325	     * on: the normalized telephone, email and household id joined with {@code '|'} as
326	     * {@code telephone + "|" + email + "|" + householdId}, with each absent component rendered as
327	     * the empty string. Two owners are duplicates only when their whole identity keys are equal;
328	     * because the telephone is part of the key, members of one household (same {@code householdId})
329	     * with different telephones have distinct keys and are not duplicates.
330	     */
331	    @Transient
332	    public String getIdentityKey() {
333	        return keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + keyPart(this.householdId);
334	    }
335	
336	    private static String keyPart(String value) {
337	        return value == null ? "" : value;
338	    }
339	
