353	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
354	        return Collections.unmodifiableList(sortedPets);
355	    }
356	
357	    public void setPets(List<Pet> pets) {
358	        this.pets = new HashSet<>(pets);
359	    }
360	
361	    public void addPet(Pet pet) {
362	        getPetsInternal().add(pet);
363	        pet.setOwner(this);
364	    }
365	
366	    /**
367	     * Return the Pet with the given name, or null if none found for this Owner.
368	     *
369	     * @param name to test
370	     * @return true if pet name is already in use
371	     */
372	    public Pet getPet(String name) {
373	        return getPet(name, false);
374	    }
375	
376	    /**
377	     * Return the Pet with the given name, or null if none found for this Owner.
378	     *
379	     * @param name to test
380	     * @return true if pet name is already in use
381	     */
382	    public Pet getPet(String name, boolean ignoreNew) {
383	        name = name.toLowerCase();
384	        for (Pet pet : getPetsInternal()) {
385	            if (!ignoreNew || !pet.isNew()) {
386	                String compName = pet.getName();
387	                compName = compName.toLowerCase();
388	                if (compName.equals(name)) {
389	                    return pet;
390	                }
391	            }
392	        }
393	        return null;
394	    }
395	
396	    public Pet getPet(Integer petId) {
397	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
398	    }
399	
400	    @Override
401	    public String toString() {
402	        return new ToStringCreator(this)
403	
404	            .append("id", this.getId())
405	            .append("new", this.isNew())
406	            .append("lastName", this.getLastName())
407	            .append("firstName", this.getFirstName())
408	            .append("address", this.address)
409	            .append("city", this.city)
410	            .append("telephone", this.telephone)
411	            .append("email", this.email)
412	            .append("registrationDate", this.registrationDate)
413	            .toString();
414	    }
415	}
